package com.primehr.rsp.evaluation.api;
import com.primehr.rsp.evaluation.api.EvaluationPolicyDtos.*; import com.primehr.rsp.evaluation.application.*; import com.primehr.security.*; import com.primehr.shared.api.*; import jakarta.validation.*; import org.springframework.http.*; import org.springframework.security.core.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/primehr/v1/rsp") public class EvaluationPolicyController {private final EvaluationPolicyService service;private final RspEvaluationPolicyPermissionGuard permission;private final AgencyScopeResolver agency;public EvaluationPolicyController(EvaluationPolicyService s,RspEvaluationPolicyPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}@GetMapping("/evaluation-policies")public PageResponse<PolicyResponse> list(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam(name="page",defaultValue="0")int page,@RequestParam(name="size",defaultValue="20")int size){permission.require(PrimeHrAction.ACCESS,t);return service.list(agency.resolveAgencyId(a),page,size);}@GetMapping("/evaluation-policies/{id}")public PolicyResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){permission.require(PrimeHrAction.ACCESS,t);return service.get(agency.resolveAgencyId(a),id);}@PostMapping("/evaluation-policies")@ResponseStatus(HttpStatus.CREATED)public PolicyResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody SavePolicy r){permission.require(PrimeHrAction.ADD,t);return service.create(agency.resolveAgencyId(a),r,c);}@PutMapping("/evaluation-policies/{id}")public PolicyResponse update(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody SavePolicy r){permission.require(PrimeHrAction.EDIT,t);return service.update(agency.resolveAgencyId(a),id,r,c);}@PostMapping("/evaluation-policies/{id}/publish")public PolicyResponse publish(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Publish r){permission.require(PrimeHrAction.PUBLISH,t);return service.publish(agency.resolveAgencyId(a),id,r,c);}@PostMapping("/evaluation-policies/{id}/successors")@ResponseStatus(HttpStatus.CREATED)public PolicyResponse successor(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition r){permission.require(PrimeHrAction.ADD,t);return service.successor(agency.resolveAgencyId(a),id,r,c);}@PutMapping("/vacancy-publications/{publicationId}/evaluation-policy")public BindingResponse bind(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String publicationId,@Valid @RequestBody BindPolicy r){permission.require(PrimeHrAction.PUBLISH,t);return service.bind(agency.resolveAgencyId(a),publicationId,r,c);}}
